"""Generate the additive static library and its readable starter documentation."""
from html import escape as e
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'


def main():
    entries = json.loads((ROOT/'catalog.json').read_text(encoding='utf-8'))
    config = json.loads((ROOT/'site-config.json').read_text(encoding='utf-8'))
    base = config['base_path']
    assert base == '/gratis-workflows/'
    assert len(entries) == 15 and len({item['id'] for item in entries}) == 15
    manifest_file = SITE/'downloads/manifest.json'
    manifest = json.loads(manifest_file.read_text(encoding='utf-8')) if manifest_file.exists() else {}
    github = config.get('github_url')
    if github and not github.startswith('https://github.com/havram23/'):
        raise ValueError('Repository-URL muss zum autorisierten GitHub-Konto gehören.')
    (ROOT/'docs/starters').mkdir(parents=True,exist_ok=True)
    SITE.mkdir(exist_ok=True)
    header = f'''<a class="skip" href="#main">Zum Inhalt</a><div class="container"><header class="site-header"><a class="brand" href="https://sans-souci.at/"><img src="{base}assets/logo-small.png" alt="" width="39" height="39"><span>Sans Souci<small>KI &amp; Automatisierung</small></span></a><div class="header-right"><nav class="nav" aria-label="Hauptnavigation"><a href="{base}" aria-current="page">Gratis-Starter</a><a href="{base}#so-gehts">So funktioniert’s</a><a href="{base}#unternehmen">Für Unternehmen</a></nav><button class="theme" type="button" data-theme-toggle aria-pressed="false">Helles Design</button></div></header></div>'''
    footer = '''<div class="container"><footer class="site-footer"><span>Sans Souci · Michael Havram · Wien</span><div><a href="https://sans-souci.at/">Firmenwebsite</a><a href="https://sans-souci.at/impressum.html">Impressum</a><a href="https://sans-souci.at/datenschutz.html">Datenschutz</a></div></footer></div>'''

    def page(title, description, content, slug='', schema=None):
        structured = json.dumps(schema,ensure_ascii=False).replace('<','\\u003c') if schema else '{}'
        return f'''<!doctype html><html lang="de" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description,quote=True)}"><title>{e(title)} · Sans Souci</title><link rel="canonical" href="{config['canonical_origin']}{base}{slug}"><link rel="icon" href="{base}assets/logo-small.png"><link rel="stylesheet" href="{base}assets/site.css"><script defer src="{base}assets/site.js"></script><script type="application/ld+json">{structured}</script></head><body>{header}{content}{footer}</body></html>'''

    cards=[]
    catalog_lines=['# Kostenlose Workflow-Bibliothek\n', '| Starter | Format | Ergebnis |', '| --- | --- | --- |']
    for index,item in enumerate(entries,1):
        slug=item['id']
        search=' '.join([item['title'],item['summary'],item['category'],item['format']]).lower()
        cards.append(f'''<article class="card" data-starter="{slug}" data-group="{e(item['category'])}" data-format="{item['format']}" data-search="{e(search,quote=True)}"><div class="card-top"><span class="index">{index:02d}</span><span>{item['format']} · kostenlos</span></div><h3>{e(item['title'])}</h3><p>{e(item['summary'])}</p><div class="card-output"><strong>Das erhalten Sie</strong>{e(item['output'])}</div><a href="{base}{slug}/">Anleitung &amp; Download <span aria-hidden="true">↗</span><span class="sr-only"> · {e(item['title'])}</span></a></article>''')
        catalog_lines.append(f"| [{item['title']}](starters/{slug}.md) | {item['format']} | {item['output']} |")
        steps='\n'.join(f'{i}. {step}' for i,step in enumerate(item['steps'],1))
        guide=f"# {item['title']}\n\n{item['summary']}\n\n**Eingabe:** {item['input']}\n\n**Ergebnis:** {item['output']}\n\n## Start\n\n" + ('Die JSON-Datei in eine eigene n8n-Instanz importieren:\n\n' if item['format']=='n8n' else 'Im entpackten Projektordner zuerst `output` anlegen. Keine zusätzlichen Python-Pakete erforderlich.\n\n') + f"```text\n{item['command']}\n```\n\n{steps}\n\n## Grenzen\n\n{item['limits']}\n\nVorhandene Dateien werden nicht überschrieben. Beispiele sind synthetisch. Eigene Ergebnisse vor Übernahme oder Weitergabe prüfen.\n\n## Wenn mehr gebraucht wird\n\n{item['next']} Persönliche Unterstützung: https://sans-souci.at/#kontakt\n"
        (ROOT/'docs/starters'/f'{slug}.md').write_text(guide,encoding='utf-8')
        archive=manifest.get(slug,{})
        checksum=archive.get('sha256','Wird beim Paketbau ergänzt.')
        size=round(archive.get('bytes',0)/1024,1)
        steps_html=''.join(f'<li>{e(step)}</li>' for step in item['steps'])
        github_link=f'<a class="button secondary" href="{e(github,quote=True)}">Quellcode auf GitHub ↗</a>' if github else ''
        detail=f'''<main id="main" class="container"><nav class="breadcrumb" aria-label="Brotkrumennavigation"><a href="{base}">Gratis-Starter</a> / <span aria-current="page">{e(item['title'])}</span></nav><section class="detail-hero"><p class="eyebrow">{e(item['category'])} · {item['format']} · MIT-Lizenz</p><h1>{e(item['title'])}</h1><p class="intro">{e(item['summary'])}</p></section><div class="detail-layout"><div><section><h2>Eine klare Eingabe. Ein prüfbares Ergebnis.</h2><dl class="io-list"><div><dt>Eingabe</dt><dd>{e(item['input'])}</dd></div><div><dt>Ausgabe</dt><dd>{e(item['output'])}</dd></div></dl></section><section><h2>So starten Sie</h2><p>{'Vorlage in n8n importieren und zuerst mit den enthaltenen Beispielen manuell ausführen.' if item['format']=='n8n' else 'Archiv entpacken, im Projektordner den Ordner output anlegen und das Beispiel ausführen.'}</p><div class="codebox"><pre id="starter-command">{e(item['command'])}</pre><button class="copy" type="button" data-copy="starter-command">{'Dateipfad' if item['format']=='n8n' else 'Befehl'} kopieren</button><p class="quiet" role="status" aria-live="polite"></p></div><ol>{steps_html}</ol></section><section><h2>Was dieser Starter abdeckt</h2><p class="notice">{e(item['limits'])}</p><p>Alle Beispiele sind synthetisch. Prüfen Sie das Ergebnis, bevor Sie eigene Daten übernehmen oder weitergeben. Vorhandene Ausgabedateien werden nicht überschrieben.</p></section><section><h2>Wenn aus dem Beispiel ein Prozess wird</h2><p>{e(item['next'])}</p><a class="button secondary" href="{config['contact_url']}">Integration besprechen ↗</a></section></div><aside class="detail-aside"><p class="eyebrow">Frei verwenden &amp; anpassen</p><h2>Ihr Starter-Paket.</h2><p>Quellcode, Beispiel und Anleitung. Kostenlos, ohne Registrierung.</p><a class="button" href="{base}downloads/{slug}.zip" download>Starter herunterladen ↓</a>{github_link}<p class="quiet">ZIP · {size:g} KiB · MIT-Lizenz</p><details><summary>Prüfsumme anzeigen</summary><p class="integrity">SHA-256<br>{checksum}</p></details><p class="quiet">{'Benötigt eine eigene n8n-Instanz. Hosting oder Cloud können kostenpflichtig sein.' if item['format']=='n8n' else 'Python 3.11+. Keine externen Pakete für diesen Starter.'}</p><a class="fallback-download" href="{base}downloads/all-starters.zip" download>Alle 15 Starter herunterladen</a></aside></div></main>'''
        schema={'@context':'https://schema.org','@type':'SoftwareSourceCode','name':item['title'],'description':item['summary'],'isAccessibleForFree':True,'programmingLanguage':'JavaScript' if item['format']=='n8n' else 'Python','license':'https://opensource.org/license/mit','url':config['canonical_origin']+base+slug+'/'}
        if github:schema['codeRepository']=github
        target=SITE/slug;target.mkdir(exist_ok=True)
        (target/'index.html').write_text(page(item['title'],item['summary'],detail,slug+'/',schema),encoding='utf-8')
    (ROOT/'docs/KATALOG.md').write_text('\n'.join(catalog_lines)+'\n',encoding='utf-8')
    categories=['','Datenqualität','Marketing & Planung','Betrieb','n8n']
    chips=''.join(f'<button type="button" data-category="{e(category)}" aria-pressed="{str(not category).lower()}">{e(category or "Alle Starter")}</button>' for category in categories)
    repo_cta=f'<a class="text-link" href="{e(github,quote=True)}">Quellcode auf GitHub ↗</a>' if github else '<a class="text-link" href="#so-gehts">Ohne Registrierung starten →</a>'
    content=f'''<main id="main"><div class="container"><section class="hero"><div><p class="eyebrow">Die kostenlose Workflow-Werkstatt</p><h1>Weniger Handarbeit.<br><em>Ein guter Anfang.</em></h1><p class="intro">Praktische Starter für saubere Daten, klare Übergaben und nachvollziehbare Abläufe. Mit offenem Code, Beispielen und einer verständlichen Anleitung.</p><div class="actions"><a class="button" href="#bibliothek">Passenden Starter finden <span aria-hidden="true">↗</span></a>{repo_cta}</div><p class="quiet">Kostenlos · MIT-Lizenz · Auch kommerziell nutzbar</p></div><aside class="hero-note"><div class="topline"><span>VOM EXPORT ZUM ERGEBNIS</span><span class="mini-tag">STARTER 01</span></div><ol class="flow"><li><span class="number">01</span><div><strong>Beispiel ausprobieren</strong><p>Synthetische Daten, klarer Einstieg.</p></div></li><li><span class="number">02</span><div><strong>Regeln anpassen</strong><p>Offener Code, eigene Entscheidung.</p></div></li><li><span class="number">03</span><div><strong>Ergebnis prüfen</strong><p>Erst danach in den Prozess übernehmen.</p></div></li></ol><p class="quiet">Kleine Werkzeuge für einen konkreten nächsten Schritt.</p></aside></section><div class="facts"><div class="fact"><strong>15 kostenlose Starter</strong><span>Python und n8n-Vorlagen</span></div><div class="fact"><strong>Ohne Registrierung</strong><span>Direkter Download als ZIP</span></div><div class="fact"><strong>Mit Beispielen</strong><span>Synthetisch und nachvollziehbar</span></div><div class="fact"><strong>Für eigene Systeme</strong><span>Code lesen, testen und anpassen</span></div></div><section class="section" id="bibliothek"><div class="section-heading"><div><p class="eyebrow">Die Bibliothek</p><h2>Welche Aufgabe darf leichter werden?</h2></div><p>Mit einem kleinen, abgegrenzten Problem beginnen. Danach entscheiden, was sich zu integrieren lohnt.</p></div><div class="filters"><label class="search-field">Starter durchsuchen<input type="search" id="search" maxlength="150" placeholder="Zum Beispiel CSV, Kalender oder Monitor" autocomplete="off"></label><label>Format<select id="format"><option value="">Alle Formate</option><option value="Python">Python</option><option value="n8n">n8n</option></select></label></div><div class="chips" role="group" aria-label="Aufgabenbereich">{chips}</div><div class="result-row"><span id="result-count" role="status" aria-live="polite">15 von 15 Startern</span><button type="button" id="reset">Filter zurücksetzen</button></div><div class="cards">{''.join(cards)}</div><div class="empty" id="empty" hidden>Kein passender Starter gefunden. Versuchen Sie einen allgemeineren Suchbegriff oder setzen Sie die Filter zurück.</div><noscript><p>Alle Starter sind ohne JavaScript erreichbar. Die Suche und Filter benötigen JavaScript.</p></noscript><p class="quiet">Die Suche läuft in Ihrem Browser. Dateien werden über diese Seite nicht hochgeladen.</p></section></div><div class="band"><section class="container section" id="so-gehts"><p class="eyebrow">Von der Idee zum ersten Lauf</p><h2>Überschaubar anfangen. Bewusst weitergehen.</h2><div class="steps"><article><span class="step-label">01 / AUSWÄHLEN</span><h3>Eine Aufgabe abgrenzen.</h3><p>Wählen Sie den Starter, dessen Ein- und Ausgabe zu Ihrem Problem passen. Die Grenzen stehen direkt dabei.</p></article><article><span class="step-label">02 / AUSPROBIEREN</span><h3>Mit Beispielen lernen.</h3><p>Entpacken, Anleitung lesen und lokal testen. Python-Starter brauchen keine zusätzlichen Bibliotheken.</p></article><article><span class="step-label">03 / ENTSCHEIDEN</span><h3>Passend integrieren.</h3><p>Für regelmäßige Nutzung werden Datenquellen, Berechtigungen, Fehlerwege und Zuständigkeiten festgelegt.</p></article></div><div class="actions"><a class="button secondary" href="{base}downloads/all-starters.zip" download>Alle Starter herunterladen ↓</a><a class="text-link" href="https://sans-souci.at/tools/">Weitere kostenlose Tools ↗</a></div></section></div><section class="container section" id="unternehmen"><p class="eyebrow">Wenn mehr gebraucht wird</p><h2>Der Starter hilft beim Anfang.<br>Wir helfen beim verlässlichen Betrieb.</h2><div class="comparison"><article><p class="eyebrow">Kostenlos &amp; eigenständig</p><h3>Ein Werkzeug für Ihre Aufgabe.</h3><ul><li>Offener Code und Beispieldaten</li><li>Lokale Ausführung und klare Dateiformate</li><li>Anleitung, Grenzen und Prüfschritte</li><li>Freie Anpassung unter MIT-Lizenz</li></ul></article><article><p class="eyebrow">Persönliche Unterstützung</p><h3>Ein Prozess für Ihr Unternehmen.</h3><ul><li>Anbindung an CRM, ERP und interne Systeme</li><li>Fehlerbehandlung und menschliche Freigaben</li><li>Workflow-Monitor, Teamrollen und Zuständigkeiten</li><li>Einführung, Wartung und laufende Betreuung</li></ul><a class="button" href="{config['contact_url']}">Automatisierung besprechen ↗</a></article></div></section><section class="container section faq" id="fragen"><p class="eyebrow">Gut zu wissen</p><h2>Bevor Sie starten.</h2><details><summary>Ist die Nutzung wirklich kostenlos?</summary><p>Der originale Code und die Anleitungen sind unter MIT kostenlos nutzbar, auch kommerziell. Eigene Infrastruktur, n8n Cloud und angebundene Dienste können separate Kosten verursachen. Es gibt keinen versteckten Kaufabschluss auf dieser Seite.</p></details><details><summary>Werden meine Dateien hochgeladen?</summary><p>Die lokalen Datenwerkzeuge senden keine Dateien an einen Dienst. Der Monitor-Client sendet nur beim ausdrücklichen Aufruf Statusmetadaten an Ihr konfiguriertes Ziel. Die n8n-Beispiele enthalten keine externen Aufrufe.</p></details><details><summary>Sind die Vorlagen sofort produktionsfertig?</summary><p>Es sind abgegrenzte Starter. Eingaben, Berechtigungen, Ausnahmen und Zielsysteme müssen für Ihren Betrieb geprüft werden. Die n8n-Dateien und ihre Code-Knoten sind strukturell getestet; ein echter Importtest in Ihrer n8n-Version bleibt erforderlich.</p></details><details><summary>Kann ich die Werkzeuge ohne Sans Souci verwenden?</summary><p>Ja. Der Code ist frei zugänglich und anpassbar. Unterstützung bei Integration oder Betrieb ist ein separates Angebot.</p></details><details><summary>Welche Unterstützung ist möglich?</summary><p>Wir klären Datenquellen, Automatisierungsumfang, Fehlerwege und den laufenden Betrieb. Daraus entsteht ein projektbezogenes Angebot. Die Firmenwebsite und die kostenlosen Starter bleiben frei erreichbar.</p></details></section></main>'''
    schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Sans Souci – kostenlose Workflow-Starter','url':config['canonical_origin']+base,'isAccessibleForFree':True,'mainEntity':{'@type':'ItemList','numberOfItems':len(entries),'itemListElement':[{'@type':'ListItem','position':i,'name':item['title'],'url':config['canonical_origin']+base+item['id']+'/'} for i,item in enumerate(entries,1)]}}
    (SITE/'index.html').write_text(page('Kostenlose Workflow-Starter','15 kostenlose Python- und n8n-Starter mit Beispielen, offenem Code und Anleitungen für Datenqualität, Planung und Betrieb.',content,schema=schema),encoding='utf-8')
    urls=[config['canonical_origin']+base]+[config['canonical_origin']+base+x['id']+'/' for x in entries]
    (SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(url)+'</loc></url>' for url in urls)+'</urlset>',encoding='utf-8')
    print(json.dumps({'starter_pages':len(entries),'catalog_pages':1,'github_link_configured':bool(github)}))


if __name__=='__main__':main()
